        if (request.guests() > room.capacity()) {
            throw new HotelException(
                    ErrorCode.CAPACITY_EXCEEDED,
                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
        }
        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
            throw new HotelException(
                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
        }
        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
        return store.add(request, price);
    }

    public Reservation find(long reservationId) {
        return store.find(reservationId)
                .orElseThrow(() -> new HotelException(
                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    }

    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    public synchronized Reservation confirm(long reservationId) {
        Reservation reservation = find(reservationId);
        if (reservation.status() != ReservationStatus.PENDING) {
            throw notAllowed(reservation, "confirm");
        }
        reservation.confirmPayment();
        store.update(reservation);
        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
        emailSender.send(
                reservation.guest().email(),
                "Reserva confirmada - " + HOTEL_NAME,
                confirmationEmailBody(reservation, receipt));
        return reservation;
    }

    /**
     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
     * reservation was never paid, so nothing comes back).
     */
    public synchronized Reservation cancel(long reservationId) {
        Reservation reservation = find(reservationId);
        if (reservation.status() != ReservationStatus.PENDING
                && reservation.status() != ReservationStatus.CONFIRMED) {
            throw notAllowed(reservation, "cancel");
        }
        BigDecimal refund = switch (reservation.ratePlan()) {
            case STANDARD -> reservation.amountPaid();
            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
        };
        reservation.cancel(refund);
        store.update(reservation);
        return reservation;
    }

    public synchronized Reservation checkIn(long reservationId) {
        Reservation reservation = find(reservationId);
        if (reservation.status() != ReservationStatus.CONFIRMED) {
            throw notAllowed(reservation, "check in");
        }
        reservation.changeStatus(ReservationStatus.CHECKED_IN);
        store.update(reservation);
        return reservation;
    }

    /** The guest leaves: the stay is closed and the final receipt is handed over. */
    public synchronized ReservationReceipt checkOut(long reservationId) {
        Reservation reservation = find(reservationId);
        if (reservation.status() != ReservationStatus.CHECKED_IN) {
            throw notAllowed(reservation, "check out");
        }
        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
        store.update(reservation);
        return new ReservationReceipt(reservation, roomOf(reservation));
    }

    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
    public ReservationReceipt receiptCopy(long reservationId) {
        Reservation reservation = find(reservationId);
        if (!reservation.isPaid()) {
            throw notAllowed(reservation, "issue a receipt for");
        }
        return new ReservationReceipt(reservation, roomOf(reservation));
    }

    private Room roomOf(Reservation reservation) {
        return rooms.find(reservation.roomNumber()).orElseThrow();
    }

    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
        return "Olá, " + reservation.guest().name() + "!\n\n"
                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
                + receipt.text() + "\n"
                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
                + "Até breve!\n";
    }

    private static HotelException notAllowed(Reservation reservation, String operation) {
        return new HotelException(
                ErrorCode.OPERATION_NOT_ALLOWED,
                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
    }
}
package hotel.reservations;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import javax.sql.DataSource;

/** Keeps the reservations in the database. */
public final class ReservationStore {

    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
    private static final String EXCLUSION_VIOLATION = "23P01";

    private final DataSource dataSource;

    public ReservationStore(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    /** Saves a new reservation; the database numbers it. */
    Reservation add(NewReservation request, Price price) {
        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
        try (Connection connection = dataSource.getConnection();
                PreparedStatement statement = connection.prepareStatement(insert)) {
            statement.setInt(1, request.roomNumber());
            statement.setString(2, request.guest().name());
            statement.setString(3, request.guest().email());
            statement.setString(4, request.guest().cpf());
            statement.setDate(5, Date.valueOf(request.checkIn()));
            statement.setDate(6, Date.valueOf(request.checkOut()));
            statement.setInt(7, request.guests());
            statement.setString(8, request.ratePlan().name());
            statement.setInt(9, price.nights());
            statement.setBigDecimal(10, price.subtotal());
            statement.setBigDecimal(11, price.discount());
            statement.setBigDecimal(12, price.total());
            statement.setString(13, ReservationStatus.PENDING.name());
            statement.setBigDecimal(14, PriceCalculator.cents(BigDecimal.ZERO));
            try (ResultSet generated = statement.executeQuery()) {
                generated.next();
                return new Reservation(generated.getLong("id"), request, price);
            }
        } catch (SQLException failure) {
            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
                        "room " + request.roomNumber() + " is taken on some of those nights");
            }
            throw new IllegalStateException("could not save the reservation", failure);
        }
    }

    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
    void update(Reservation reservation) {
        try (Connection connection = dataSource.getConnection();
                PreparedStatement statement = connection.prepareStatement(
                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
            statement.setString(1, reservation.status().name());
            statement.setBigDecimal(2, reservation.amountPaid());
            statement.setBigDecimal(3, reservation.refund());
            statement.setLong(4, reservation.id());
            statement.executeUpdate();
        } catch (SQLException failure) {
            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
        }
    }

    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
        try (Connection connection = dataSource.getConnection();
                PreparedStatement select = connection.prepareStatement(
                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
                                + "AND check_in < ? AND ? < check_out")) {
            select.setInt(1, roomNumber);
            select.setDate(2, Date.valueOf(checkOut));
            select.setDate(3, Date.valueOf(checkIn));
            try (ResultSet rows = select.executeQuery()) {
                return rows.next();
            }
        } catch (SQLException failure) {
            throw new IllegalStateException("could not check room " + roomNumber, failure);
        }
    }

    public Optional<Reservation> find(long id) {
        try (Connection connection = dataSource.getConnection();
                PreparedStatement select = connection.prepareStatement(
                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
            select.setLong(1, id);
            try (ResultSet rows = select.executeQuery()) {
                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
            }
        } catch (SQLException failure) {
            throw new IllegalStateException("could not read reservation " + id, failure);
        }
    }

    public List<Reservation> all() {
        try (Connection connection = dataSource.getConnection();
                PreparedStatement select = connection.prepareStatement(
                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
                ResultSet rows = select.executeQuery()) {
            List<Reservation> reservations = new ArrayList<>();
            while (rows.next()) {
                reservations.add(read(rows));
            }
            return reservations;
        } catch (SQLException failure) {
            throw new IllegalStateException("could not read the reservations", failure);
        }
    }

    private static Reservation read(ResultSet row) throws SQLException {
        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), row.getString("guest_cpf"));
        NewReservation request = new NewReservation(
                row.getInt("room_number"),
                guest,
                row.getDate("check_in").toLocalDate(),
                row.getDate("check_out").toLocalDate(),
                row.getInt("guests"),
                RatePlan.valueOf(row.getString("rate_plan")));
        Price price = new Price(
                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
                row.getBigDecimal("total"));
        return new Reservation(
                row.getLong("id"),
                request,
                price,
                ReservationStatus.valueOf(row.getString("status")),
                row.getBigDecimal("amount_paid"),
                row.getBigDecimal("refund"));
    }
}

