    private static final String HEAD = """
            {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
             "checkIn": "2027-07-10", "checkOut": "2027-07-12", "guests": 2, "ratePlan": "STANDARD",
            """;

    @Test
    void identifiesTheGuestInExactlyOneWay() throws Exception {
        for (String ids : new String[] {
                "", "\"guestCpf\": \"1\", \"guestPassport\": \"P1\", \"guestCountry\": \"Chile\"",
                "\"companyCnpj\": \"1\"", "\"companyName\": \"X\"", "\"guestPassport\": \"P1\"",
                "\"guestCountry\": \"Chile\"", "\"guestCpf\": \"1\", \"companyCnpj\": \"1\", \"companyName\": \"X\""}) {
            String body = HEAD + (ids.isEmpty() ? "\"x\": 1}" : ids + "}");
            HttpResponse<String> response = post("/reservations", body);
            assertEquals(400, response.statusCode(), ids);
            assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
        }
    }

    @Test
    void bookingForACompanyAndAForeigner() throws Exception {
        JsonNode company = json.readTree(post("/reservations",
                HEAD + "\"companyCnpj\": \"12.345.678/0001-90\", \"companyName\": \"Tecnosul Ltda\"}").body());
        assertTrue(company.get("guestCpf").isNull());
        assertTrue(company.get("guestPassport").isNull());
        assertEquals("Tecnosul Ltda", company.get("companyName").asText());

        JsonNode foreigner = json.readTree(post("/reservations", HEAD.replace("07-10", "08-10").replace("07-12", "08-12")
                + "\"guestPassport\": \"X1234567\", \"guestCountry\": \"United Kingdom\"}").body());
        long id = foreigner.get("id").asLong();
        assertEquals("United Kingdom", json.readTree(get("/reservations/" + id).body()).get("guestCountry").asText());
        post("/reservations/" + id + "/confirmation", "");
        JsonNode document = json.readTree(get("/reservations/" + id + "/document").body());
        assertEquals("Booking receipt", document.get("title").asText());
        assertTrue(document.get("guestCpf").isNull());
        assertTrue(document.get("companyCnpj").isNull());
        assertTrue(document.get("text").asText().startsWith("Booking receipt no. " + id));
    }
}
